/* === Caption Transition Animations === */

/* 1. Pop In */
@keyframes captionPopIn {
  0% { transform: scale(0); opacity: 0; }
  70% { transform: scale(1.1); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}
.anim-pop .word-span {
  opacity: 0;
  animation: captionPopIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}

/* 2. Slide Up Fade */
@keyframes captionSlideUpFade {
  0% { transform: translateY(30px); opacity: 0; }
  100% { transform: translateY(0); opacity: 1; }
}
.anim-slide-up .word-span {
  opacity: 0;
  animation: captionSlideUpFade 0.4s ease-out forwards;
}

/* Hind intrinsic entrance — slide-up + fade + de-blur (mirrors the reference
   @keyframes show).  Applied PER WORD: each word stays hidden (opacity:0) until its
   own spoken time, then slides up + fades in.  The inline animation-delay is set to
   the word's (start - blockStart) offset; during export the capture-freeze rule
   overrides it with --cap-delay so each frame seeks to the right point. */
/* No animated filter: blur(). An animating blur can never be composited — WebKit re-runs the
   gaussian pass on every frame on the main thread — and on a 4K project that is what made Hind's
   per-word reveal stutter in Safari (Chrome absorbed the cost). Same call, and the same reason, as
   .anim-gamer-door, which dropped the reference's blur for exactly this. The slide-up + fade is
   what reads as the reveal; over 0.2s the de-blur was barely visible anyway. */
@keyframes hindShow {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}
.hind-word {
  opacity: 0;
  animation: hindShow 0.2s ease forwards;
}

/* Smooth — 3-line kinetic caption. Each line runs its OWN entrance:
   line 1 (prefix) slides in from the LEFT, the MAIN word pops UP from the bottom,
   line 3 (suffix) slides in from the RIGHT. Delays stagger them (0 / 0.2s / 0.4s).
   During export the capture-freeze rule seeks each via --cap-delay so the download
   animates identically. Keep durations in sync with THEME_ENTRANCE_SEC.smooth. */
@keyframes smoothSlideLeft {
  0%   { opacity: 0; transform: translateX(-30px); }
  100% { opacity: 1; transform: translateX(0); }
}
@keyframes smoothSlideRight {
  0%   { opacity: 0; transform: translateX(30px); }
  100% { opacity: 1; transform: translateX(0); }
}
@keyframes smoothPopUp {
  0%   { opacity: 0; transform: translateY(26px) scale(0.8); }
  70%  { opacity: 1; transform: translateY(0) scale(1.08); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
.smooth-line-1 {
  opacity: 0;
  animation: smoothSlideLeft 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}
.smooth-line-2 {
  opacity: 0;
  animation: smoothPopUp 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) 0.2s forwards;
}
.smooth-line-3 {
  opacity: 0;
  animation: smoothSlideRight 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94) 0.4s forwards;
}

/* Solo — each word fades in at its own spoken time. Opacity-only (no transform in the
   keyframe) because Solo words carry their own translate/scale/rotate inline transform,
   which an animated transform would clobber. */
@keyframes soloFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}
.solo-word {
  opacity: 0;
  animation: soloFadeIn 0.25s ease forwards;
}

/* 3. Slide From Left */
@keyframes captionSlideFromLeft {
  0% { transform: translateX(-50px); opacity: 0; }
  100% { transform: translateX(0); opacity: 1; }
}
.anim-slide-left .word-span {
  opacity: 0;
  animation: captionSlideFromLeft 0.4s ease-out forwards;
}

/* 3b. Slide From Right — mirror of Slide From Left */
@keyframes captionSlideFromRight {
  0% { transform: translateX(50px); opacity: 0; }
  100% { transform: translateX(0); opacity: 1; }
}
.anim-slide-right .word-span {
  opacity: 0;
  animation: captionSlideFromRight 0.4s ease-out forwards;
}

/* 4. Bounce Drop */
@keyframes captionBounceDrop {
  0% { transform: translateY(-50px); opacity: 0; }
  40% { transform: translateY(0); opacity: 1; }
  60% { transform: translateY(-15px); }
  80% { transform: translateY(0); }
  90% { transform: translateY(-5px); }
  100% { transform: translateY(0); opacity: 1; }
}
.anim-bounce-drop .word-span {
  opacity: 0;
  animation: captionBounceDrop 0.6s ease-out forwards;
}

/* 5. Typewriter (Character based) */
@keyframes captionTypeWriter {
  from { opacity: 0; }
  to { opacity: 1; }
}
.anim-typewriter .char-span {
  opacity: 0;
  animation: captionTypeWriter 0.05s linear forwards;
}

/* 6. Flicker/Glitch */
@keyframes captionFlicker {
  0%, 19%, 21%, 23%, 25%, 54%, 56%, 100% { opacity: 1; transform: scale(1); }
  20%, 24%, 55% { opacity: 0; transform: scale(0.95); }
}
.anim-flicker .word-span {
  opacity: 0;
  animation: captionPopIn 0.2s forwards, captionFlicker 0.5s ease-in-out forwards 0.2s;
}

/* 7. Character Snap/Scale */
@keyframes captionCharSnap {
  0% { transform: scale(2) rotate(15deg); opacity: 0; }
  100% { transform: scale(1) rotate(0deg); opacity: 1; }
}
.anim-char-snap .char-span {
  opacity: 0;
  animation: captionCharSnap 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

/* 8. Rotate In 3D */
@keyframes captionRotateIn3D {
  0% { transform: perspective(400px) rotateX(90deg); opacity: 0; }
  100% { transform: perspective(400px) rotateX(0deg); opacity: 1; }
}
.anim-rotate-3d .word-span {
  opacity: 0;
  transform-origin: bottom;
  animation: captionRotateIn3D 0.5s ease-out forwards;
}

/* 9. Blur Reveal */
@keyframes captionBlurReveal {
  0% { filter: blur(10px); opacity: 0; transform: scale(1.1); }
  100% { filter: blur(0px); opacity: 1; transform: scale(1); }
}
.anim-blur .word-span {
  opacity: 0;
  animation: captionBlurReveal 0.5s ease-out forwards;
}

/* 10. Word Spring (Hormozi style) */
@keyframes captionSpringWord {
  0% { transform: scale(0.5); opacity: 0; color: #fff; }
  50% { transform: scale(1.2); opacity: 1; color: #fff; }
  100% { transform: scale(1); opacity: 1; color: #fff; }
}
.anim-spring .word-span {
  opacity: 0;
  animation: captionSpringWord 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
.anim-spring.playing .word-span.past {
  color: #94a3b8;
  transform: scale(0.9);
  transition: all 0.3s ease;
}

/* Common helper classes */
.word-span {
  display: inline-block;
  white-space: pre;
}
.char-span {
  display: inline-block;
  white-space: pre;
}

/* ─── Block-level transitions for themes that can't use per-word .word-span ───
 * Shine, Fusion, Triple, Pill, Sliding-Highlight, Popup-Chat, Notification themes
 * render their text inside a single visual element (background-clip:text gradient,
 * pill badge, highlight box, etc.) where wrapping individual words in spans would
 * break the rendering. For these themes the transition CSS class lands on a
 * .block-anim-target wrapper, and these rules animate the whole wrapper instead
 * of per-word. Same animations, same feel — just applied at block granularity.
 * Note: anim-blur is intentionally omitted because filter:blur breaks
 * background-clip:text gradient rendering in WebKit.
 */
.anim-pop > .block-anim-target {
  opacity: 0;
  animation: captionPopIn 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}
.anim-slide-up > .block-anim-target {
  opacity: 0;
  animation: captionSlideUpFade 0.4s ease-out forwards;
}
.anim-slide-left > .block-anim-target {
  opacity: 0;
  animation: captionSlideFromLeft 0.4s ease-out forwards;
}
.anim-slide-right > .block-anim-target {
  opacity: 0;
  animation: captionSlideFromRight 0.4s ease-out forwards;
}
.anim-bounce-drop > .block-anim-target {
  opacity: 0;
  animation: captionBounceDrop 0.6s ease-out forwards;
}
.anim-typewriter > .block-anim-target {
  opacity: 0;
  animation: captionTypeWriter 0.3s linear forwards;
}
.anim-flicker > .block-anim-target {
  opacity: 0;
  animation: captionPopIn 0.2s forwards, captionFlicker 0.5s ease-in-out forwards 0.2s;
}
.anim-char-snap > .block-anim-target {
  opacity: 0;
  animation: captionCharSnap 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}
.anim-rotate-3d > .block-anim-target {
  opacity: 0;
  transform-origin: bottom;
  animation: captionRotateIn3D 0.5s ease-out forwards;
}
.anim-blur > .block-anim-target {
  opacity: 0;
  /* Use scale-only fade instead of blur — filter:blur breaks background-clip:text */
  animation: captionPopIn 0.5s ease-out forwards;
}
.anim-spring > .block-anim-target {
  opacity: 0;
  animation: captionSpringWord 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}

/* ─── Notification-only entrance animations ───
 * Applied directly to .notif-wrapper. The wrapper's own default animation is
 * removed (replaced) by these so the per-block transition controls the entrance.
 */
@keyframes notifSlideDown {
  0%   { opacity: 0; transform: translateY(-60px) scale(0.92); }
  60%  { opacity: 1; transform: translateY(4px) scale(1); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}
.anim-notif-slide-down.notif-wrapper {
  opacity: 0;
  transform: translateY(-60px) scale(0.92);
  animation: notifSlideDown 0.7s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  animation-delay: 0.05s;
}

@keyframes notifPop {
  0%   { opacity: 0; transform: scale(0); }
  70%  { opacity: 1; transform: scale(1.06); }
  100% { opacity: 1; transform: scale(1); }
}
.anim-notif-pop.notif-wrapper {
  opacity: 0;
  transform: scale(0);
  transform-origin: center;
  animation: notifPop 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  animation-delay: 0.05s;
}

@keyframes notifSlideLeft {
  0%   { opacity: 0; transform: translateX(-120%); }
  100% { opacity: 1; transform: translateX(0); }
}
.anim-notif-slide-left.notif-wrapper {
  opacity: 0;
  transform: translateX(-120%);
  animation: notifSlideLeft 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  animation-delay: 0.05s;
}

/* ─── The same three entrances, applied to an emoji/sticker ───
 * Stickers may use ANY transition in the picker, including the notification ones. A sticker is a
 * single element (.sticker-anim) rather than a .notif-wrapper card, so the notif-* classes need
 * their own selectors here — the keyframes above are reused as-is.
 */
.anim-notif-slide-down.sticker-anim {
  opacity: 0;
  transform: translateY(-60px) scale(0.92);
  animation: notifSlideDown 0.7s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  animation-delay: 0.05s;
}
.anim-notif-pop.sticker-anim {
  opacity: 0;
  transform: scale(0);
  transform-origin: center;
  animation: notifPop 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  animation-delay: 0.05s;
}
.anim-notif-slide-left.sticker-anim {
  opacity: 0;
  transform: translateX(-120%);
  animation: notifSlideLeft 0.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  animation-delay: 0.05s;
}

